<?php
namespace ProjectPress\API;use ProjectPress\Includes\Project\Communication\NotificationRepository;use ProjectPress\Includes\Project\Communication\NotificationService;use ProjectPress\Includes\Project\Core\ProjectPermissions;use ProjectPress\Includes\Project\People\TimeSheetRepository;use ProjectPress\Includes\Project\People\TimeSheetService;use ProjectPress\Includes\Project\ProjectManager;use WP_Error;use WP_REST_Request;use WP_REST_Response;use WP_REST_Server;if(!defined('ABSPATH')){exit;}final class PeopleCommunicationRoutes{public static function register_routes():void{foreach(array('timesheets','notifications')as$type){register_rest_route(Routes::NAMESPACE,"/projects/(?P<project>[A-Za-z0-9_-]+)/{$type}",array(array('methods'=>WP_REST_Server::READABLE,'callback'=>array(self::class,'index'),'permission_callback'=>array(self::class,'can_read')),array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array(self::class,'create'),'permission_callback'=>array(self::class,'can_edit'))));register_rest_route(Routes::NAMESPACE,"/projects/(?P<project>[A-Za-z0-9_-]+)/{$type}/(?P<id>\\d+)",array('methods'=>WP_REST_Server::DELETABLE,'callback'=>array(self::class,'delete'),'permission_callback'=>array(self::class,'can_edit')));}}public static function index(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$repo=self::repo($r);return self::success(array_map(static fn($x)=>$x->to_array(),$repo->for_project($p->get_id())));}public static function create(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$repo=self::repo($r);$service=self::service($r,$repo);$input='timesheets'===self::type($r)?array('user_id'=>absint($r->get_param('user_id')),'minutes'=>absint($r->get_param('minutes')),'work_date'=>sanitize_text_field((string)$r->get_param('work_date')),'description'=>sanitize_textarea_field((string)$r->get_param('description'))):array('recipient_id'=>absint($r->get_param('recipient_id')),'message'=>sanitize_textarea_field((string)$r->get_param('message')));return self::domain($service->create($p->get_id(),$input),201);}public static function delete(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$repo=self::repo($r);$record=$repo->find(absint($r['id']));if(!$record||$record->get_project_id()!==$p->get_id())return new WP_Error('projectpress_record_not_found',__('Record not found.','projectpress'),array('status'=>404));$x=self::service($r,$repo)->delete($record);return is_wp_error($x)?$x:self::success(array('deleted'=>(bool)$x,'id'=>$record->get_id()));}public static function can_read(WP_REST_Request$r){$p=self::project($r);return is_wp_error($p)?$p:((new ProjectPermissions())->can_view($p)?true:self::forbidden());}public static function can_edit(WP_REST_Request$r){$p=self::project($r);return is_wp_error($p)?$p:((new ProjectPermissions())->can_edit($p)?true:self::forbidden());}private static function project(WP_REST_Request$r){$p=ProjectManager::get_instance()->resolve(sanitize_text_field((string)$r->get_param('project')));return is_wp_error($p)?new WP_Error('projectpress_rest_project_not_found',__('Project not found.','projectpress'),array('status'=>404)):$p;}private static function type(WP_REST_Request$r):string{return false!==strpos($r->get_route(),'notifications')?'notifications':'timesheets';}private static function repo(WP_REST_Request$r){return'timesheets'===self::type($r)?new TimeSheetRepository():new NotificationRepository();}private static function service(WP_REST_Request$r,$repo){return'timesheets'===self::type($r)?new TimeSheetService($repo,ProjectManager::get_instance()->repository(),new ProjectPermissions()):new NotificationService($repo,ProjectManager::get_instance()->repository(),new ProjectPermissions());}private static function success($data,int$status=200):WP_REST_Response{return new WP_REST_Response(array('success'=>true,'data'=>$data),$status);}private static function domain($x,int$status=200){return is_wp_error($x)?$x:self::success(is_object($x)&&method_exists($x,'to_array')?$x->to_array():$x,$status);}private static function forbidden():WP_Error{return new WP_Error('projectpress_rest_forbidden',__('You do not have permission to perform this action.','projectpress'),array('status'=>rest_authorization_required_code()));}}
